import io
from rich.console import Console
from rich.file_proxy import FileProxy

class NoIsatty:
    def write(self, text):
        pass
    def flush(self):
        pass

def test_no_isatty():
    console = Console()
    wrapped_file = NoIsatty()
    proxy = FileProxy(console, wrapped_file)

    # This is how Console does it:
    isatty = getattr(proxy, "isatty", None)
    print(f"isatty is: {isatty}")
    if isatty:
        print(f"isatty() is: {isatty()}")

if __name__ == "__main__":
    test_no_isatty()

import sys
from rich.console import Console
from rich.file_proxy import FileProxy

class MockTTY:
    def write(self, text):
        pass
    def flush(self):
        pass
    def isatty(self):
        return True

def test_tty_proxy():
    console = Console()
    wrapped_file = MockTTY()
    proxy = FileProxy(console, wrapped_file)

    print(f"wrapped_file isatty: {wrapped_file.isatty()}")
    print(f"proxy isatty: {proxy.isatty()}")

if __name__ == "__main__":
    test_tty_proxy()

